'use strict';
const $=s=>document.querySelector(s);
const icon=id=>`<svg aria-hidden="true"><use href="#i-${id}"/></svg>`;
const LETTER_HTML="<article class=\"cesar-letter\"><p class=\"letter-date\">Vigo, 14 de noviembre de 1893</p><p>Profesor Criptóbal:</p><p>Venga a Vigo con Lola. La baliza del puerto ha desaparecido y alguien está enviando órdenes con mi nombre. No sé en quién confiar.</p><p>En este sobre encontrará una pieza de latón. Guárdela: dos letras pueden señalar el camino.</p><p>Al llegar al Casco Vello, enfrente la <strong>A</strong> a la <strong>D</strong> y busque:</p><strong class=\"cipher\">WDOOHU</strong><p>Pregunten allí por Clotilde Tic-Tac. Les contaré el resto cuando sea seguro.</p><p class=\"letter-signature\">César</p></article>";
const ARRIVAL="Por fin, Vigo. Apenas hemos bajado del barco y ya tengo las botas mojadas. Espero que la carta de ese tal César justifique el viaje, Lola.";
const puzzles=[
{"title": "La carta de César", "short": "La carta de César", "topic": "Criptografía", "place": "La maleta · Casco Vello", "icon": "key", "item": "✉", "evidence": "La primera pista de César", "objective": "Descubre adónde quiere enviarte César", "detail": "La carta y la pieza de latón viajaron con vosotros hasta Vigo.", "action": "Examinar la carta", "intro": "La carta os ha traído hasta Vigo. Junto a ella venía esta pieza con dos discos de letras. César dejó una instrucción: «Enfrente la A a la D». ¿Qué lugar esconde la palabra WDOOHU?", "body": "<details class=\"letter-fold\"><summary>Leer la carta completa, firmada por César</summary><article class=\"cesar-letter\"><p class=\"letter-date\">Vigo, 14 de noviembre de 1893</p><p>Profesor Criptóbal:</p><p>Venga a Vigo con Lola. La baliza del puerto ha desaparecido y alguien está enviando órdenes con mi nombre. No sé en quién confiar.</p><p>En este sobre encontrará una pieza de latón. Guárdela: dos letras pueden señalar el camino.</p><p>Al llegar al Casco Vello, enfrente la <strong>A</strong> a la <strong>D</strong> y busque:</p><strong class=\"cipher\">WDOOHU</strong><p>Pregunten allí por Clotilde Tic-Tac. Les contaré el resto cuando sea seguro.</p><p class=\"letter-signature\">César</p></article></details><div id=\"brass-object\"></div><div class=\"puzzle-paper compact-cipher\"><strong class=\"cipher\">WDOOHU</strong><p>Relaciona cada letra del mensaje con la letra exterior que queda enfrente.</p></div><label class=\"field-label\" for=\"answer\">¿Adónde debéis ir?</label><input id=\"answer\" type=\"text\" placeholder=\"Escribe el lugar\" autocomplete=\"off\" maxlength=\"40\" required>", "answer": "TALLER", "hints": ["Gira el disco hasta que la A exterior quede enfrente de la D interior. Busca después la W en el círculo interior.", "Con A frente a D, la W interior está frente a la T exterior. D corresponde a A; O, a L. Continúa con O, H y U."], "learning": "La pieza relaciona dos alfabetos desplazados. Para leer el mensaje se recorre esa relación al revés: W corresponde a T. Este sistema tiene solo 25 desplazamientos distintos; sirve para aprender, pero no para proteger secretos actuales.", "finding": "WDOOHU dice TALLER. La carta de César os conduce al taller de Clotilde Tic-Tac, en el Casco Vello. Ella reconoce la pieza de latón: pertenecía al encargado de la baliza."},
{title:'Un telegrama impostor',short:'El falso telegrama',topic:'Ciberseguridad',place:'El taller de Clotilde',icon:'search',item:'⌁',evidence:'El telegrama falso',objective:'Detecta el telegrama falso',detail:'Clotilde recibió dos mensajes. Uno intenta robar la clave del taller.',action:'Examinar telegramas',intro:'Clotilde reconoce a César: es el encargado de la baliza. Le han llegado dos telegramas supuestamente suyos. Su taller usa el dominio taller-vigo.test. Compara los telegramas: ¿cuál intenta engañarla para que entregue su contraseña? Todos los dominios de este caso son ficticios.',body:'<label class="choice"><input type="radio" name="choice" value="a" required><span><strong>Telegrama A · Archivo del puerto de Vigo</strong><small>avisos@taller-vigo.test</small>«El inventario está listo. Revísalo en tu archivo habitual. No necesitamos tu contraseña.»</span></label><label class="choice"><input type="radio" name="choice" value="b"><span><strong>Telegrama B · ALERTA URGENTE</strong><small>seguridad@taller-vlgo.test</small>«¡Tu taller será clausurado en diez minutos! Responde con tu contraseña para verificar tu identidad.»</span></label>',answer:'b',hints:['Compara letra por letra el dominio del remitente con taller-vigo.test.','En el segundo mensaje, vigo se ha convertido en vlgo. También pide una contraseña y mete prisa.'],learning:'El phishing suplanta a alguien de confianza. Revisa el dominio completo, desconfía de la urgencia y nunca compartas contraseñas. Un remitente que parece correcto tampoco garantiza autenticidad: verifica por un canal conocido.',finding:'El telegrama B suplanta a Clotilde. Entre sus papeles aparece la combinación de una caja: trece, escrito en cuatro bits.'},
{title:'El cerrojo de dos símbolos',short:'La caja binaria',topic:'Informática',place:'La caja del taller',icon:'lock',item:'▦',evidence:'El registro de acceso',objective:'Abre el cerrojo binario',detail:'Cuatro interruptores protegen un registro. La combinación decimal es 13.',action:'Abrir la caja',intro:'La caja solo entiende ceros y unos. Cada interruptor aporta su valor cuando está encendido. Activa los necesarios para representar el número 13.',body:'<div class="puzzle-paper"><div class="binary-row">'+[8,4,2,1].map((v,i)=>`<div class="bit"><small>${v}</small><button type="button" class="bit-button" data-bit="${i}" aria-pressed="false" aria-label="Bit de valor ${v}">0</button></div>`).join('')+'<div class="binary-total">Valor actual: <strong id="binary-total">0</strong> · Objetivo: <strong>13</strong></div></div>',answer:13,hints:['Cada posición vale el doble que la de su derecha: 1, 2, 4, 8. Suma solo las encendidas.','13 = 8 + 4 + 1. El interruptor que vale 2 debe estar apagado.'],learning:'Un bit puede valer 0 o 1. En binario, cada posición representa una potencia de dos. 1101₂ = 8 + 4 + 0 + 1 = 13. Los ordenadores combinan bits para representar datos.',finding:'La caja contiene un registro firmado de la baliza. Para leerlo, Lola necesita acceso al archivo, pero no permiso para modificarlo.'},
{title:'La llave justa',short:'Los permisos',topic:'Seguridad digital',place:'El archivo del puerto',icon:'key',item:'⚿',evidence:'El permiso de lectura',objective:'Protege el archivo de pruebas',detail:'Da a Lola el acceso mínimo para consultar el registro sin alterar las pruebas.',action:'Asignar permisos',intro:'Lola solo debe leer el registro. Marca todos los permisos que necesita y deja sin marcar los demás.',body:'<label class="choice"><input type="checkbox" name="permission" value="read"><span><strong>Leer el registro</strong><small>Consultar las entradas del archivo.</small></span></label><label class="choice"><input type="checkbox" name="permission" value="write"><span><strong>Editar el registro</strong><small>Cambiar las entradas guardadas.</small></span></label><label class="choice"><input type="checkbox" name="permission" value="delete"><span><strong>Borrar el registro</strong><small>Eliminar las pruebas del caso.</small></span></label><label class="choice"><input type="checkbox" name="permission" value="admin"><span><strong>Administrar las cuentas</strong><small>Dar o quitar permisos a otras personas.</small></span></label>',answer:'read',hints:['Necesitar leer un documento no implica necesitar cambiarlo.','Selecciona solo «Leer el registro». Los otros permisos no hacen falta para su tarea.'],learning:'El principio de mínimo privilegio consiste en dar únicamente los permisos necesarios. Así se reduce el daño que puede causar un error o una cuenta comprometida. Los registros deben protegerse frente a cambios no autorizados.',finding:'Lola recupera una copia verificada del registro. A las 21:14, alguien activó el traslado automático de la baliza.'},
{title:'La huella entre la niebla',short:'La gran deducción',topic:'Deducción',place:'El almacén de O Berbés',icon:'search',item:'◷',evidence:'La orden de traslado',objective:'Reconstruye lo que ocurrió',detail:'Cruza la hora, la acción y el destino. Las pruebas cuentan una historia.',action:'Resolver el misterio',intro:'El registro verificado muestra todos los accesos de esa noche. La baliza desapareció la noche anterior a vuestra llegada, a las 21:14. Compara las cuentas, las acciones y las horas. ¿Qué conclusión respaldan estas pruebas?',body:'<div class="puzzle-paper"><table class="log-table"><caption>Registro de la baliza · 14 de noviembre de 1893</caption><thead><tr><th>Hora</th><th>Cuenta</th><th>Acción</th><th>Destino</th></tr></thead><tbody><tr><td>21:10</td><td>Clotilde</td><td>Consulta</td><td>Archivo</td></tr><tr><td>21:12</td><td>Tomás Tostón</td><td>Consulta</td><td>Archivo</td></tr><tr><td>21:14</td><td>Tornillín 07</td><td>Traslado</td><td>O Berbés</td></tr><tr><td>21:16</td><td>César</td><td>Consulta</td><td>Archivo</td></tr></tbody></table></div><label class="choice"><input type="radio" name="choice" value="ada" required><span>Clotilde robó la baliza porque consultó el archivo primero.</span></label><label class="choice"><input type="radio" name="choice" value="automaton"><span>La cuenta Tornillín 07 ordenó el traslado al almacén de O Berbés. Aún hay que investigar quién controlaba esa cuenta.</span></label><label class="choice"><input type="radio" name="choice" value="vale"><span>César borró la baliza, porque fue el último en entrar.</span></label>',answer:'automaton',hints:['La consulta de un archivo no es un traslado. Busca la acción que coincide con las 21:14.','El registro identifica una cuenta, una acción y un destino. No demuestra por sí solo quién estaba detrás de la cuenta.'],learning:'Investigar consiste en cruzar evidencias, no en adivinar culpables. Un registro ayuda a reconstruir hechos, pero una cuenta no siempre identifica a la persona que la utilizó. Distingue lo demostrado de lo que falta por verificar.',finding:'¡La baliza está en el almacén de O Berbés! Tornillín 07 la trasladó siguiendo una instrucción antigua. El telegrama falso era una segunda amenaza: Clotilde cambió sus credenciales por un canal seguro y protegió el archivo.'}
];
const KEY='niebla-cifra-vigo-v1';
let state={completed:[],hintUses:0,seen:[],dialogue:0};
try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved&&Array.isArray(saved.completed)){let count=0;while(count<5&&saved.completed.includes(count))count++;state={...state,completed:Array.from({length:count},(_,i)=>i),hintUses:Number.isFinite(saved.hintUses)?Math.max(0,saved.hintUses):0,seen:Array.isArray(saved.seen)?saved.seen.filter(x=>['book','clock','door'].includes(x)):[]};}}catch{}
let activePuzzle=0,bits=[0,0,0,0],hintIndex=0,toastTimer,ambient=null,lastFocus=null,dialogueReturnToExplore=false;
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{toast('Guardado no disponible: mantén esta pestaña abierta');}}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500);}
function openModal(kicker,html){const modal=$('#modal');if(!modal.open)lastFocus=document.activeElement;modal.classList.toggle('letter-screen',kicker==='LA CARTA DE CÉSAR');modal.classList.toggle('puzzle-screen',kicker.startsWith('ENIGMA '));modal.classList.toggle('result-screen',kicker==='DEDUCCIÓN CORRECTA'||kicker.includes('CASO CERRADO'));$('#modal-kicker').textContent=kicker;$('#modal-content').innerHTML=html;if(!modal.open)modal.showModal();modal.scrollTop=0;}
function closeModal(){$('#modal').close();if(lastFocus&&document.contains(lastFocus))lastFocus.focus();}
function setExploring(enabled){$('#game').classList.toggle('exploring',enabled);$('#dialogue-next').setAttribute('aria-label',enabled?'Abrir el enigma actual':'Siguiente diálogo');layoutScene();if(enabled){$('#speaker-name').textContent='Casco Vello · Vigo';$('#dialogue-text').textContent='Examina los objetos de la calle para encontrar nuevas pistas. En nuestra maleta están la carta de César y la pieza que nos envió.';$('#dialogue-text').scrollTop=0;const world=$('.scene-world');world.scrollLeft=(world.scrollWidth-world.clientWidth)/2;}}
function setDialogue(text,speaker='Profesor Criptóbal',partner='iris'){setExploring(false);$('#speaker-name').textContent=speaker;$('#dialogue-text').textContent=text;$('#dialogue-text').scrollTop=0;$('#game').classList.toggle('partner-speaking',speaker!=='Profesor Criptóbal');$('#partner-sprite').src=`assets/${partner}-v2.png`;$('#partner-sprite').alt=partner==='ada'?'Clotilde Tic-Tac, la relojera':'Lola Bitácora con su cuaderno';}
function render(){const count=state.completed.length;const p=puzzles[Math.min(count,4)];const hotspot=$('.hs-letter');hotspot.dataset.puzzle=Math.min(count,4);hotspot.setAttribute('aria-label',count===5?'Ver el desenlace':p.action);hotspot.querySelector('label').textContent=count===5?'Caso resuelto':count===0?'La carta de César':p.short;dialogueReturnToExplore=count>0;if(count)setDialogue(count===5?'Lo has conseguido, detective. Has seguido las pruebas sin confundir una sospecha con un hecho. Esa es la verdadera llave de cualquier misterio.':`${puzzles[count-1].finding} Sigamos investigando.`);}
function openPuzzle(i){if(i>state.completed.length){toast('Resuelve el enigma anterior para descubrir esta pista.');return;}if(i===0){showLetter();return;}activePuzzle=i;bits=[0,0,0,0];hintIndex=0;const p=puzzles[i];openModal(`ENIGMA ${String(i+1).padStart(3,'0')} · ${p.topic.toUpperCase()}`,`<div class="puzzle-meta">${icon(p.icon)} ${p.place.toUpperCase()} <span>·</span> ${state.completed.includes(i)?'YA RESUELTO':'SIN LÍMITE DE TIEMPO'}</div><h2 class="modal-title">${p.title}</h2><p class="modal-intro">${p.intro}</p><form id="puzzle-form">${p.body}<div class="puzzle-actions"><button type="button" class="secondary-button" id="hint-button">${icon('spark')} Una pista</button><button class="primary-button" type="submit">Comprobar ${icon('arrow')}</button></div><div id="hint-output" aria-live="polite"></div><div class="feedback" id="feedback" role="status" aria-live="polite"></div></form>`);$('#puzzle-form').addEventListener('submit',checkAnswer);$('#hint-button').addEventListener('click',showHint);document.querySelectorAll('.bit-button').forEach(btn=>btn.addEventListener('click',()=>{const n=Number(btn.dataset.bit);bits[n]=1-bits[n];btn.textContent=bits[n];btn.classList.toggle('on',Boolean(bits[n]));btn.setAttribute('aria-pressed',String(Boolean(bits[n])));$('#binary-total').textContent=bits.reduce((sum,bit,index)=>sum+bit*[8,4,2,1][index],0);}));}
function showHint(){const p=puzzles[activePuzzle];if(hintIndex<p.hints.length){$('#hint-output').innerHTML=`<div class="hint"><strong>Pista ${hintIndex+1}.</strong> ${p.hints[hintIndex]}</div>`;hintIndex++;state.hintUses++;save();$('#hint-button').innerHTML=hintIndex===2?'Todas las pistas vistas':`${icon('spark')} Otra pista`;if(hintIndex===2)$('#hint-button').disabled=true;}}
function checkAnswer(event){event.preventDefault();let answer;if(activePuzzle===0)answer=$('#answer').value.trim().normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase();else if(activePuzzle===2)answer=bits.reduce((sum,bit,i)=>sum+bit*[8,4,2,1][i],0);else if(activePuzzle===3)answer=[...document.querySelectorAll('[name=permission]:checked')].map(el=>el.value).join(',');else answer=document.querySelector('[name=choice]:checked')?.value;const p=puzzles[activePuzzle];if(answer!==p.answer){if($('#modal').classList.contains('letter-screen')){$('#feedback').textContent='No encaja todavía. Prueba otra palabra.';$('#answer').setAttribute('aria-invalid','true');$('#answer').focus();return;}$('#feedback').textContent='Aún no encaja con las pruebas. Revisa los detalles o pide una pista. Puedes intentarlo de nuevo sin perder puntos.';return;}if(!state.completed.includes(activePuzzle)){state.completed.push(activePuzzle);save();}render();openModal('DEDUCCIÓN CORRECTA',`<div class="success-mark">${icon('check')}</div><div class="puzzle-meta">PRUEBA AÑADIDA AL CUADERNO</div><h2 class="modal-title">¡Elemental, detective!</h2><p class="modal-intro">${p.finding}</p><div class="learning"><strong>LO QUE ACABAS DE DESCUBRIR</strong><p>${p.learning}</p></div><button class="primary-button" id="next-puzzle">${activePuzzle===4?'Ver el desenlace':'Seguir la pista'} ${icon('arrow')}</button>`);$('#next-puzzle').addEventListener('click',()=>activePuzzle===4?showEnding():openPuzzle(activePuzzle+1));}
function showEnding(){openModal('EXPEDIENTE 001 · CASO CERRADO',`<div class="medal">✧</div><div class="puzzle-meta">DISTINTIVO OBTENIDO · DETECTIVE DEL CÓDIGO</div><h2 class="modal-title">La niebla se disipa.</h2><p class="modal-intro">En el almacén de O Berbés, entre redes y engranajes, encontráis la baliza intacta. César os espera junto a ella: «¡Han recibido mi carta! Temía que interceptaran también el sobre». César y Clotilde descubren que una antigua orden de mantenimiento seguía activa en Tornillín 07. No hubo un robo: hubo un traslado sin comunicar.</p><p class="modal-intro">El telegrama impostor era real, pero no explicaba la desaparición. Al comprobar cada prueba has evitado acusar a alguien sin fundamento, y has ayudado a Clotilde a proteger su taller.</p><div class="learning"><strong>CINCO HABILIDADES PARA LLEVARTE CONTIGO</strong><p>Descifrar un código · Reconocer el phishing · Leer binario · Limitar permisos · Separar hechos de sospechas.</p></div><p class="modal-intro">«Un misterio resuelto es una pregunta mejor formulada», sonríe Despistes. Lola guarda la carta de César y la pieza de latón en la maleta. Sobre la ría vuelve a sonar la baliza. Su primera noche en Vigo acaba con un misterio resuelto.</p><button class="primary-button" data-panel="notebook">Revisar mis descubrimientos ${icon('book')}</button>`);}
function showNotebook(){openModal('ARCHIVO PERSONAL',`<h2 class="modal-title">Mi cuaderno de detective</h2><p class="modal-intro">Las pruebas se conservan. Las conexiones las haces tú. ${state.completed.length} de 5 descubrimientos.</p><button class="letter-menu-link" data-panel="letter">${icon('book')} Carta recibida de César · Ver el objeto</button><div class="evidence-list">${state.completed.length?state.completed.map(i=>`<article class="evidence-card"><span class="evidence-icon">${puzzles[i].item}</span><div><h3>${puzzles[i].evidence}</h3><p>${puzzles[i].finding}</p><div class="learning"><strong>${puzzles[i].topic.toUpperCase()}</strong><p>${puzzles[i].learning}</p></div><button class="secondary-button" data-puzzle="${i}">Volver a resolver</button></div></article>`).join(''):'<div class="empty-note">Todavía no hay pruebas en tu cuaderno.<br>La carta de César ya está en tu equipaje. Examínala junto a la pieza de latón.</div>'}</div>`);}
function showCharacters(){openModal('ELENCO ORIGINAL · ASSETS DEL JUEGO',`<h2 class="modal-title">Nunca investigas a solas.</h2><p class="modal-intro">Tres mentes curiosas. Tres formas de mirar un mismo misterio.</p><div class="character-grid"><article class="character-card"><div class="character-art" role="img" aria-label="Criptóbal Despistes, detective de abrigo verde y lupa"></div><div class="character-info"><small>EL MENTOR</small><h3>Criptóbal Despistes</h3><p>Criptógrafo, profesor y coleccionista de preguntas. Cree que la paciencia es más útil que una lupa.</p></div></article><article class="character-card"><div class="character-art iris" role="img" aria-label="Lola Bitácora, joven inventora con gafas y cuaderno"></div><div class="character-info"><small>LA APRENDIZ</small><h3>Lola Bitácora</h3><p>Inventora de quince años. Ve patrones donde los demás solo ven números y cables enredados.</p></div></article><article class="character-card"><div class="character-art ada" role="img" aria-label="Clotilde Tic-Tac, relojera con un mecanismo de latón"></div><div class="character-info"><small>LA RELOJERA</small><h3>Clotilde Tic-Tac</h3><p>Custodia los mecanismos del puerto de Vigo. Sus relojes guardan secretos; ella, todas las llaves.</p></div></article></div><div class="asset-download"><a class="secondary-button" href="assets/vale-v2.png" download>Criptóbal · PNG ↓</a><a class="secondary-button" href="assets/iris-v2.png" download>Lola · PNG ↓</a><a class="secondary-button" href="assets/ada-v2.png" download>Clotilde · PNG ↓</a><a class="secondary-button" href="assets/vigo-casco-vello.png" download="niebla-y-cifra-escenario.png">Descargar escenario ↓</a></div>`);}
function showMap(){openModal('CARTOGRAFÍA DEL CASO',`<h2 class="modal-title">Casco Vello · Vigo</h2><p class="modal-intro">Sigue el recorrido de las pruebas. Cada enigma abre una nueva parte de la investigación.</p><div class="map-art">Vigo, 1893.<br>Una carta desde la ría.</div><ol class="map-list">${puzzles.map((p,i)=>`<li><button data-puzzle="${i}" ${i>state.completed.length?'aria-disabled="true"':''}><span>${i+1}. ${p.place}</span><small>${i<state.completed.length?'✓ INVESTIGADO':i===state.completed.length?'EXPLORAR →':'POR DESCUBRIR'}</small></button></li>`).join('')}</ol>`);}
function showProfile(){openModal('CARNÉ DE INVESTIGADOR',`<h2 class="modal-title">${state.completed.length===5?'Detective del código':'Detective en formación'}</h2><p class="modal-intro">Lo importante no es correr. Es comprender cada pista.</p><div class="profile-stats"><div><strong>${state.completed.length}/5</strong><small>Enigmas resueltos</small></div><div><strong>${state.hintUses}</strong><small>Pistas consultadas</small></div><div><strong>${state.seen.length}/3</strong><small>Objetos explorados</small></div></div><p class="modal-intro">La partida se guarda automáticamente en este navegador. No se necesitan cuentas ni datos personales.</p><button class="secondary-button" id="reset-game">Comenzar una nueva investigación</button>`);$('#reset-game').addEventListener('click',()=>{openModal('NUEVA INVESTIGACIÓN',`<h2 class="modal-title">¿Volvemos al principio?</h2><p class="modal-intro">Se borrarán las pistas y el progreso de esta partida en este navegador.</p><div class="puzzle-actions"><button class="secondary-button" data-panel="profile">Conservar mi partida</button><button class="primary-button" id="confirm-reset">Reiniciar el caso</button></div>`);$('#confirm-reset').addEventListener('click',()=>{state={completed:[],hintUses:0,seen:[],dialogue:0};save();render();setDialogue(ARRIVAL);closeModal();toast('Una nueva investigación te espera.');});});}
function showHelp(){openModal('GUÍA DE CAMPO',`<h2 class="modal-title">Toda gran aventura<br>empieza observando.</h2><ol class="help-steps"><li>Avanza con la flecha del diálogo. Al terminar la conversación podrás examinar los objetos de la calle.</li><li>Examina la carta en el escenario para ver el mensaje y el objeto.</li><li>Lee las pruebas y envía tu deducción. No hay cronómetro.</li><li>Si te atascas, pide una pista. Aprender no resta puntos.</li><li>Guarda las ideas en tu cuaderno y sigue el recorrido.</li></ol><div class="learning"><strong>PARA MENTES CURIOSAS · A PARTIR DE 10 AÑOS</strong><p>Un caso de unos 15–25 minutos. Usa Tab para recorrer los controles y Enter para activarlos. Escape cierra las ventanas. El botón de las cuatro esquinas activa la pantalla completa. Todos los retos son simulaciones ficticias.</p></div><button class="primary-button" id="help-start">Volver a la aventura ${icon('arrow')}</button>`);$('#help-start').addEventListener('click',closeModal);}
const panels={map:showMap,notebook:showNotebook,characters:showCharacters,profile:showProfile,letter:showLetter};
const inspections={"book": {"title": "La librería de don Tomás Tostón", "text": "Don Tomás asoma entre los libros. «¿Recién llegados a Vigo? Se les nota en las maletas. César pasó ayer por aquí; preguntó por un libro sobre letras que cambian de sitio». Lola se apunta el detalle.", "clue": "La pieza del sobre tiene dos alfabetos de 26 letras, sin Ñ. Observa qué letras quedan enfrentadas."}, "clock": {"title": "El reloj de Clotilde", "text": "El reloj del taller se paró a las 21:14 de ayer. Una vecina recuerda que a esa hora dejó de sonar la baliza del puerto. Lola anota ambos hechos: todavía hay que comprobar si están relacionados.", "clue": "Conserva la hora: 21:14. Más adelante podrás compararla con el registro del puerto."}, "door": {"title": "El taller de Clotilde Tic-Tac", "text": "«¡Así que ustedes son los viajeros de la carta de César!», dice Clotilde. «Me avisó de su llegada a Vigo. Enseñadme la pieza que venía en el sobre; quizá nos ayude a entender qué ocurre en el puerto». ", "clue": "La carta la escribió César. Clotilde es el contacto al que os envía en el Casco Vello."}};
document.addEventListener('click',event=>{const panel=event.target.closest('[data-panel]');if(panel){panels[panel.dataset.panel]?.();return;}const p=event.target.closest('[data-puzzle]');if(p){if(p.classList.contains('hs-letter')&&state.completed.length===5)showEnding();else openPuzzle(Number(p.dataset.puzzle));return;}const evidence=event.target.closest('[data-evidence]');if(evidence){const p=puzzles[Number(evidence.dataset.evidence)];openModal('PRUEBA RECOGIDA',`<div class="medal">${p.item}</div><h2 class="modal-title">${p.evidence}</h2><p class="modal-intro">${p.finding}</p><div class="learning"><strong>${p.topic.toUpperCase()}</strong><p>${p.learning}</p></div>`);return;}const inspect=event.target.closest('[data-inspect]');if(inspect){rememberStory();const key=inspect.dataset.inspect,p=inspections[key];if(!state.seen.includes(key)){state.seen.push(key);save();}setDialogue(p.text,key==='door'?'Clotilde Tic-Tac':'Lola Bitácora',key==='door'?'ada':'iris');dialogueReturnToExplore=true;toast(p.clue);}});
$('#close-modal').addEventListener('click',closeModal);
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
const dialogueLines=[{"speaker": "Lola Bitácora", "text": "¡Mire la ría, profesor! Vigo es todavía más bonita que en los mapas. Aunque venir hasta Galicia por una carta misteriosa… eso sí que no estaba en nuestros planes."}, {"speaker": "Profesor Criptóbal", "text": "La escribió y firmó un tal César. Nos pide ayuda: ha desaparecido la baliza del puerto y alguien envía órdenes usando su nombre."}, {"speaker": "Lola Bitácora", "text": "Y dentro del sobre venía esto. Pesa lo suyo… tiene dos discos, letras por todas partes y una pequeña muesca. No parece una moneda de recuerdo."}, {"speaker": "Profesor Criptóbal", "text": "Todavía no sabemos para qué sirve. César escribió: «Al llegar al Casco Vello, enfrente la A a la D». Después dejó seis letras: WDOOHU."}, {"speaker": "Lola Bitácora", "text": "Voy a apoyar la maleta en ese banco. Saquemos la carta y la pieza. Quizá las letras no estén ahí de adorno."}, {"speaker": "Profesor Criptóbal", "text": "Buena idea. Acabamos de llegar a Vigo y ya tenemos un lugar que encontrar. Empecemos por leer con cuidado lo que nos ha escrito César."}];
$('#dialogue-next').addEventListener('click',()=>{if($('#game').classList.contains('exploring')){state.completed.length===5?showEnding():openPuzzle(state.completed.length);return;}rememberStory();if(dialogueReturnToExplore){dialogueReturnToExplore=false;setExploring(true);return;}if(state.dialogue>=dialogueLines.length){setExploring(true);if(state.dialogue===dialogueLines.length){state.dialogue++;showLetter();}return;}const line=dialogueLines[state.dialogue];setDialogue(line.text,line.speaker);state.dialogue++;});
$('#fullscreen').addEventListener('click',async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else if(document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();else toast('El juego ya ocupa toda la ventana. Este navegador no admite el modo de pantalla completa.');}catch{toast('El navegador no permite ampliar más la ventana. El juego sigue ocupando todo el espacio disponible.');}});
document.addEventListener('fullscreenchange',()=>{const active=Boolean(document.fullscreenElement);$('#fullscreen').setAttribute('aria-pressed',String(active));$('#fullscreen').setAttribute('aria-label',active?'Salir de pantalla completa':'Activar pantalla completa');});
function showMenu(){const count=state.completed.length;openModal('LA MALETA DEL DETECTIVE',`<div class="menu-heading"><span>✦</span><h2 class="modal-title">Niebla & Cifra</h2><p>La carta de la ría</p></div><button class="letter-menu-link" data-panel="letter">${icon('book')} La carta de César y la pieza de latón</button><div class="game-menu-grid"><button data-panel="notebook">${icon('book')}<strong>Mi cuaderno</strong><small>${count} pruebas recogidas</small></button><button data-panel="map">${icon('map')}<strong>Mapa del caso</strong><small>Sigue la investigación</small></button><button data-panel="characters">${icon('users')}<strong>Personajes</strong><small>Conoce a tus compañeros</small></button><button data-panel="profile">${icon('key')}<strong>Mi partida</strong><small>Progreso y nueva aventura</small></button></div><div class="menu-objective"><span>OBJETIVO ACTUAL</span><p>${count===5?'El caso está resuelto.':puzzles[count].objective}</p></div><button id="resume-game" class="primary-button">Volver a la aventura ${icon('arrow')}</button>`);$('#resume-game').addEventListener('click',closeModal);}
$('#sound').addEventListener('click',async()=>{try{if(!ambient){const AC=window.AudioContext||window.webkitAudioContext;if(!AC){toast('Este navegador no permite el ambiente sonoro.');return;}const ctx=new AC();const gain=ctx.createGain();gain.gain.value=.022;gain.connect(ctx.destination);const buffer=ctx.createBuffer(1,ctx.sampleRate*3,ctx.sampleRate);const channel=buffer.getChannelData(0);let previous=0;for(let i=0;i<channel.length;i++){previous=(previous+Math.random()*.04-.02)/1.02;channel[i]=previous*3;}const noise=ctx.createBufferSource();noise.buffer=buffer;noise.loop=true;const filter=ctx.createBiquadFilter();filter.type='lowpass';filter.frequency.value=550;noise.connect(filter);filter.connect(gain);noise.start();ambient={ctx,on:false};}ambient.on=!ambient.on;if(ambient.on)await ambient.ctx.resume();else await ambient.ctx.suspend();$('#sound').setAttribute('aria-pressed',String(ambient.on));$('#sound').setAttribute('aria-label',ambient.on?'Desactivar ambiente sonoro':'Activar ambiente sonoro');toast(ambient.on?'Ambiente de niebla activado':'Ambiente sonoro desactivado');}catch{toast('No se ha podido activar el sonido en este navegador.');}});
render();
if(!state.completed.length)setDialogue(ARRIVAL);

function layoutScene(){const scene=$('#scene'),canvas=$('.scene-canvas'),art=$('.scene-art');const w=scene.clientWidth,h=scene.clientHeight;const exploring=$('#game').classList.contains('exploring');const iw=art.naturalWidth||1672,ih=art.naturalHeight||941;const cw=exploring?Math.max(w,h*iw/ih):w;canvas.style.width=cw+'px';canvas.style.height=h+'px';const scale=Math.max(cw/iw,h/ih);const xOffset=(cw-iw*scale)/2,yOffset=(h-ih*scale)*.53;const points={book:[.13,.54],letter:[.65,.78],clock:[.83,.39],door:[.94,.58]};for(const [key,xy] of Object.entries(points)){const el=$('.hs-'+key);el.style.left=(xy[0]*iw*scale+xOffset)+'px';el.style.top=(xy[1]*ih*scale+yOffset)+'px';}$('#explore-message span').textContent=cw>w+10?'Desliza la calle para explorar. Pulsa un objeto.':'Observa con atención. Cada detalle cuenta.';}
new ResizeObserver(layoutScene).observe($('#scene'));$('.scene-art').addEventListener('load',layoutScene);layoutScene();


function showLetter(){
  activePuzzle=0;
  openModal('LA CARTA DE CÉSAR',`<button type="button" id="letter-back" aria-label="Anterior">${icon('arrow')}<span>Anterior</span></button><div class="letter-and-object"><section class="letter-evidence" aria-label="Carta recibida antes del viaje">${LETTER_HTML}</section><section class="object-panel" aria-label="Pieza de latón y solución"><div id="brass-object"></div><form id="letter-answer-form"><div class="letter-answer-row"><input id="answer" type="text" aria-label="Solución de la carta" aria-describedby="feedback" placeholder="Tu respuesta…" autocomplete="off" spellcheck="false" maxlength="40" required><button type="submit" class="primary-button">Resolver ${icon('arrow')}</button></div><div class="feedback" id="feedback" role="status" aria-live="polite"></div></form></section></div>`);
  mountBrassObject(true);
  fitLetterScreen();
  $('#letter-back').addEventListener('click',closeModal);
  $('#letter-answer-form').addEventListener('submit',checkAnswer);
  $('#answer').addEventListener('input',()=>{$('#answer').removeAttribute('aria-invalid');$('#feedback').textContent='';});
}

function mountBrassObject(minimal=false){const host=$('#brass-object');if(!host)return;let shift=0;const alphabet='ABCDEFGHIJKLMNOPQRSTUVWXYZ';host.innerHTML=`<div class="brass-device"><svg class="brass-wheel" viewBox="0 0 320 320" role="img" aria-label="Pieza de latón con dos discos de letras"><image href="assets/dispositivo-laton.png" x="0" y="0" width="320" height="320"/><g id="outer-letters"></g><g id="inner-letters"></g></svg><div class="wheel-controls"><button type="button" class="secondary-button" data-turn="-1" aria-label="Girar el disco a la izquierda"><svg viewBox="0 0 32 32" aria-hidden="true"><path d="M8 11a10 10 0 1 1-1 12M8 4v8H1"/></svg></button>${minimal?'':'<div class="wheel-readout"><span>ALINEACIÓN</span><output id="wheel-alignment" aria-live="polite">A ↔ A</output></div>'}<button type="button" class="secondary-button" data-turn="1" aria-label="Girar el disco a la derecha"><svg viewBox="0 0 32 32" aria-hidden="true"><path d="M24 11a10 10 0 1 0 1 12M24 4v8h7"/></svg></button></div>${minimal?'':'<small>Usa las flechas para girar el disco interior.</small>'}</div>`;const letters=(radius,offset,size)=>[...alphabet].map((_,i)=>{const angle=i*2*Math.PI/26;return `<text x="${160+Math.sin(angle)*radius}" y="${160-Math.cos(angle)*radius+(radius===122&&i===0?7:0)}" text-anchor="middle" dominant-baseline="central" font-size="${size}">${alphabet[(i+offset+26)%26]}</text>`;}).join('');$('#outer-letters').innerHTML=letters(122,0,14);const update=()=>{$('#inner-letters').innerHTML=letters(88,shift,13);const output=$('#wheel-alignment');if(output)output.textContent=`A ↔ ${alphabet[shift]}`;host.querySelector('.brass-wheel').setAttribute('aria-label',`Pieza de latón: A exterior frente a ${alphabet[shift]} interior`);};host.querySelectorAll('[data-turn]').forEach(btn=>btn.addEventListener('click',()=>{shift=(shift+Number(btn.dataset.turn)+26)%26;update();}));update();}

// Measure the full composition, then fit it in both dimensions without cropping.
function fitLetterScreen(){
  const modal=$('#modal'), viewport=$('#modal-content');
  if(!modal.open||!modal.classList.contains('letter-screen'))return;
  const desk=viewport.querySelector('.letter-and-object');
  if(!desk||!viewport.clientWidth||!viewport.clientHeight)return;
  const width=Math.max(1,viewport.clientWidth-24),height=Math.max(1,viewport.clientHeight-88);
  const portrait=width<560;
  desk.classList.toggle('is-portrait',portrait);
  desk.style.width=`${portrait?Math.max(390,Math.min(470,width)):Math.max(820,Math.min(1100,width))}px`;
  const scale=Math.min(1,width/desk.offsetWidth,height/desk.offsetHeight);
  desk.style.setProperty('--evidence-scale',String(scale));
}
const evidenceViewportObserver=new ResizeObserver(fitLetterScreen);
evidenceViewportObserver.observe($('#modal-content'));
if(document.fonts)document.fonts.ready.then(fitLetterScreen);

// Keep dialogue navigation separate from solved puzzles and collected evidence.
const storyHistory=[];
function rememberStory(){
  storyHistory.push({
    text:$('#dialogue-text').textContent,
    speaker:$('#speaker-name').textContent,
    partner:$('#partner-sprite').getAttribute('src').includes('ada-v2')?'ada':'iris',
    exploring:$('#game').classList.contains('exploring'),
    dialogue:state.dialogue,
    returnToExplore:dialogueReturnToExplore
  });
  $('#story-back').disabled=false;
}
$('#story-back').addEventListener('click',()=>{
  const previous=storyHistory.pop();
  if(!previous)return;
  state.dialogue=previous.dialogue;
  dialogueReturnToExplore=previous.returnToExplore;
  setDialogue(previous.text,previous.speaker,previous.partner);
  if(previous.exploring)setExploring(true);
  $('#story-back').disabled=storyHistory.length===0;
});
